css:
/*
	common style for whole page
	This should include:
	+ page size related settings
	+ font family settings
	+ line spacing settings
*/
.print-format div,
.print-format span,
.print-format td,
.print-format h1,
.print-format h2,
.print-format h3,
.print-format h4 {
	font-family: Georgia, serif;
}

/* classic format: for-test */

.print-format-doc.print-format-doc--standard .section-label {
	font-size: 0.95em;
	font-weight: 600;
	background-color: var(--gray-100);
	border: 1px solid var(--gray-300);
	border-bottom: none;
	padding: 0.45em 0.6em;
	margin-bottom: 0;
}
.print-format-doc.print-format-doc--standard .child-table .table thead th {
	background-color: var(--gray-100) !important;
}
.print-format-doc.print-format-doc--standard .section--grid:not(:has(.field, .child-table)) {
	display: none;
}
